async function noOverflow(page){
 assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1),true);
 const clipped=await page.evaluate(()=>[...document.querySelectorAll('button,input,select,textarea')].filter(el=>{
   if(!el.getClientRects().length)return false;
   for(let parent=el.parentElement;parent&&parent!==document.body;parent=parent.parentElement){
     if(['auto','scroll'].includes(getComputedStyle(parent).overflowX)&&parent.scrollWidth>parent.clientWidth+1)return false;
   }
   const r=el.getBoundingClientRect();return r.left < -1 || r.right > innerWidth+1;
 }).map(el=>el.id||el.className));
 assert.deepEqual(clipped,[],'controls must fit outside intentional horizontal scroll containers');
 assert.deepEqual(page.errors,[]);
}
async function connectNormalApi(p,{fence=true}={}){
 const initial=await p.evaluate(()=>Object.fromEntries(mem));
 initial['users/mgr']={role:'owner',name:'運営'};initial['users/a']={role:'employee',name:'講師A'};initial['users/b']={role:'employee',name:'講師B'};
 initial['systemConfig/normalAuthority']={enabled:true,schemaVersion:1};
 const store=createStore(initial),id='model-'+apiSessions.size,model={store,commands:[]};
 model.execute=createNormalAuthority({db:store.db,serverTimestamp:()=>({__shiftlyType:'timestamp',value:'2026-11-12T00:00:00.000Z'}),todayKey:()=> '2026-11-12',...(fence?{bookingFence:{assertCanChangeStudent:async()=>true}}:{})});apiSessions.set(id,model);
 await p.evaluate(id=>{window.respond=async (fields,name)=>{
   // Compatibility fixture: old normal backend supports calendar only. It is not
   // the private seasonal implementation and must never fake its capabilities.
   if(name==='seasonalAuthorityApi'){
     if(fields.action==='capabilities')return {protocolVersion:3,operations:['saveCalendar']};
     if(fields.action!=='saveCalendar')throw Object.assign(Error('未対応の講習API'),{code:'failed-precondition'});
     const snap=await window.respond({kind:'inspect',requestId:'inspect-'+fields.requestId,date:fields.date},'normalAuthorityApi'),row=snap.calendar[fields.collection];
     const stable=v=>JSON.stringify(v==null?null:Array.isArray(v)?v.map(x=>JSON.parse(stable(x))):typeof v==='object'?Object.fromEntries(Object.keys(v).sort().map(k=>[k,JSON.parse(stable(v[k]))])):v);
     if(stable(fields.expectedValue)!==stable(row?.value??null))throw Object.assign(Error('他の端末で内容が変更されました'),{code:'aborted'});
     const value=fields.value?Object.fromEntries(Object.entries(fields.value).filter(([k])=>!['date','type'].includes(k))):null;
     const r=await window.respond({kind:'calendar',requestId:fields.requestId,collection:fields.collection,date:fields.date,expected:row?.token??null,...(fields.remove?{remove:true}:{value})},'normalAuthorityApi');return {...r,protocolVersion:3};
   }
   const payload=await(await fetch('/__normal-api?session='+id,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(fields)})).json();
   if(payload.error)throw Object.assign(Error(payload.error.message),{code:payload.error.code});
   if(!['inspect','planStudentDelete','planRestore'].includes(fields.kind)){
     const revive=v=>Array.isArray(v)?v.map(revive):v&&typeof v==='object'?(v.__shiftlyType==='timestamp'?{toDate:()=>new Date(v.value),toMillis:()=>new Date(v.value).getTime(),seconds:new Date(v.value).getTime()/1000}:Object.fromEntries(Object.entries(v).map(([k,x])=>[k,revive(x)]))):v;
     mem.clear();for(const [path,data]of payload.records)mem.set(path,revive(data));
     const rows=col=>[...mem].filter(([path])=>path.startsWith(col+'/')&&path.split('/').length===2).map(([path,data])=>({id:path.split('/')[1],...data}));
     const dict=col=>Object.fromEntries(rows(col).map(({id,...d})=>[id,d]));
     Object.assign(test.state,{entries:rows('timetableEntries'),students:rows('schoolStudents'),teacherWeeklyWork:dict('teacherWeeklyWork'),teacherDateWork:dict('teacherDateWork'),teacherAbsences:dict('teacherDayAbsences'),closures:dict('schoolClosures'),openDays:dict('schoolOpenDays'),examEvents:dict('schoolEvents')});
   }
   if(window.loseApiResponse&&!['inspect','planStudentDelete','planRestore'].includes(fields.kind)){window.loseApiResponse=false;throw Object.assign(Error('lost response'),{code:'functions/unavailable'});}
   return payload.result;
 };},id);
 return model;
}
