async function seedManualCourse(p,enabled){await seed(p);await p.evaluate(enabled=>{const s=test.state,c={id:'c',name:'講習',startDate:s.date,endDate:s.date,periods:[{start:'17:30',end:'18:25'}]};s.courses=[c];const entry={id:'manual',courseId:'c',studentId:'s',studentName:'生徒S',teacherUid:'a',teacherName:'講師A',grade:'中1',school:'学校',date:s.date,start:'17:30',end:'18:25',subject:'数学',status:'scheduled',memo:'元のメモ',nextDates:[]};s.entries=[entry];const {id,...data}=entry;mem.set('timetableEntries/manual',data);window.respond=({action})=>action==='getSettings'?{course:c,settings:enabled===null?null:{enabled}}:{teachers:[{id:'a',defaultCapacity:2},{id:'b',defaultCapacity:2}]};s.availabilityStatus.c='ready';for(const uid of ['a','b'])s.availability.set('c/'+uid,{slots:[s.date+'_0']});test.nav('adminSchedule')},enabled)}
await check('予約有効講習の手動授業もメモ保存前に停止し、DBを変更しない',async()=>{const p=await open();await seedManualCourse(p,true);await p.locator('.lesson-card').click();await p.locator('#memoContent').fill('新メモ');await p.locator('#memoForm button[type=submit]').click();await p.waitForFunction(()=>document.getElementById('message').textContent.includes('講習予約管理'));assert.equal(await p.evaluate(()=>ops.length),0);assert.equal(await p.evaluate(()=>mem.get('timetableEntries/manual').memo),'元のメモ');await p.context().close()});
await check('予約設定のない通常の講習授業は従来どおりメモを保存',async()=>{const p=await open();await seedManualCourse(p,null);await p.locator('.lesson-card').click();await p.locator('#memoContent').fill('新メモ');await p.locator('#memoForm button[type=submit]').click();await p.waitForFunction(()=>!document.getElementById('detailDialog').open);assert.equal(await p.evaluate(()=>mem.get('timetableEntries/manual').memo),'新メモ');await p.context().close()});
await check('予約設定の取得失敗時は書込みを停止',async()=>{const p=await open();await seedManualCourse(p,false);await p.evaluate(()=>window.apiError='通信失敗');await p.locator('.lesson-card').click();await p.locator('#memoContent').fill('新メモ');await p.locator('#memoForm button[type=submit]').click();await p.waitForFunction(()=>document.getElementById('message').textContent.includes('予約設定を確認できません'));assert.equal(await p.evaluate(()=>ops.length),0);await p.context().close()});
await check('予約有効講習の配置確定は直接書込みを停止し仮配置を保持',async()=>{const p=await open();await seedManualCourse(p,true);await p.evaluate(()=>{test.openCourseEditor('c');test.nav('courseEditor')});await p.waitForFunction(()=>test.courseEditorCapacity.ready);await p.evaluate(()=>test.courseEditorMove('manual',{teacherUid:'b',date:'2026-11-12',start:'17:30',end:'18:25'}));await p.locator('#editorSave').click();await p.waitForFunction(()=>!test.courseEditor.busy);assert.equal(await p.evaluate(()=>ops.length),0);assert.equal(await p.evaluate(()=>test.courseEditor.draft.get('manual').teacherUid),'b');assert.equal(await p.evaluate(()=>mem.get('timetableEntries/manual').teacherUid),'a');await p.context().close()});
await check('予約授業がある生徒の氏名変更は主データ保存前に停止',async()=>{const p=await open();await seed(p);await p.evaluate(()=>{mem.set('timetableEntries/b_reserved',{studentId:'s',courseId:'c'});test.openStudent('s')});await p.locator('#studentName').fill('変更後');await p.locator('#studentForm button[type=submit]').click();await p.waitForFunction(()=>document.getElementById('message').textContent.includes('講習予約管理'));assert.equal(await p.evaluate(()=>ops.length),0);assert.equal(await p.evaluate(()=>mem.get('schoolStudents/s').name),'生徒S');await p.context().close()});
