await check('統合: 通常勤務曜日外は黒枠、臨時出勤よりコマ別欠席を優先',async()=>{const p=await open('/?work-feature=1');await seedWork(p);await p.evaluate(()=>test.nav('adminLessons'));assert.equal(await workCell(p,'a',1).evaluate(e=>e.classList.contains('is-absent')),true);await p.evaluate(()=>{test.state.teacherDateWork['2026-11-17_a']={availablePeriods:[1,2]};test.state.teacherAbsences['2026-11-17_a']={date:'2026-11-17',teacherUid:'a',absentPeriods:[2]};test.regularEditor.onData()});assert.equal(await workCell(p,'a',1).evaluate(e=>e.classList.contains('is-absent')),false);assert.equal(await workCell(p,'a',2).evaluate(e=>e.classList.contains('is-absent')),true);assert.equal(await workCell(p,'a',3).evaluate(e=>e.classList.contains('is-absent')),true);assert.equal(await p.evaluate(()=>test.lessonsOnDate('2026-11-24')[0].teacherUid),'a');assert.equal(await p.evaluate(()=>ops.length),0);await p.context().close()});
