await check('統合: 仮振替中に勤務曜日が変わると確定を停止',async()=>{const p=await open('/?work-feature=1');await seedWork(p);await p.evaluate(()=>test.nav('adminLessons'));await workCell(p,'a',1).locator('.normal-entry').click();await workCell(p,'b',1).click();await p.evaluate(()=>{test.state.teacherWeeklyWork.b={weekdays:[1,4]};test.regularEditor.onData()});assert.equal(await p.locator('#normalPublish').isDisabled(),true);assert.match(await p.locator('#normalEditorWarning').innerText(),/他の端末/);assert.equal(await p.evaluate(()=>ops.length),0);await p.context().close()});
await check('統合: 講師勤務曜日の保存は監査と同時、snapshot待ちでも表示を保持',async()=>{const p=await open('/?work-feature=1');await seedWork(p);await p.evaluate(()=>test.nav('teacherManagement'));await p.locator('#workWeekDays input[value="2"]').check();await p.locator('#workWeekSave').click();await p.waitForFunction(()=>!test.teacherWorkPage.isBusy());assert.deepEqual(await p.evaluate(()=>mem.get('teacherWeeklyWork/a').weekdays),[1,2,4]);assert.equal(await p.locator('#workWeekDays input[value="2"]').isChecked(),true);assert.ok(await p.evaluate(()=>ops.some(x=>x[1].startsWith('auditLogs/'))));assert.equal(await p.evaluate(()=>ops.some(x=>x[1].startsWith('schoolStudents/')||x[1].startsWith('specialCourses/'))),false);await p.context().close()});
await check('統合: 臨時出勤の保存・解除は通常勤務曜日に戻す',async()=>{const p=await open('/?work-feature=1');await seedWork(p);await p.evaluate(()=>test.nav('teacherManagement'));await p.locator('#workSpecialDate').fill('2026-11-17');await p.locator('#workSpecialDate').dispatchEvent('change');await p.locator('#workDayPeriods input[value="1"]').check();await p.locator('#workDayPeriods input[value="2"]').check();await p.locator('#workDaySave').click();await p.waitForFunction(()=>mem.has('teacherDateWork/2026-11-17_a'));assert.equal(await p.evaluate(()=>test.teacherWorkPage.works('a','2026-11-17',1)),true);await p.locator('#workDayClear').click();await p.waitForFunction(()=>!mem.has('teacherDateWork/2026-11-17_a'));assert.equal(await p.evaluate(()=>test.teacherWorkPage.works('a','2026-11-17',1)),false);await p.context().close()});
await check('統合: 同じ講師管理タブを押しても未保存の変更を失わない',async()=>{const p=await open('/?work-feature=1');await seedWork(p);await p.evaluate(()=>test.nav('teacherManagement'));await p.locator('#workWeekDays input[value="2"]').check();await p.evaluate(()=>test.nav('teacherManagement'));assert.equal(await p.locator('#workWeekDays input[value="2"]').isChecked(),true);await p.evaluate(()=>test.nav('courses'));await p.evaluate(()=>test.nav('teacherManagement'));assert.equal(await p.locator('#workWeekDays input[value="2"]').isChecked(),false);assert.equal(await p.evaluate(()=>ops.length),0);await p.context().close()});
