await check('統合: 勤務設定保存中の遷移とログアウト後の遅延書込を停止',async()=>{const p=await open('/?work-feature=1');await seedWork(p);await p.evaluate(()=>test.nav('teacherManagement'));await p.locator('#workWeekDays input[value="2"]').check();await p.evaluate(()=>pauseGetDoc=true);await p.locator('#workWeekSave').click();await p.waitForFunction(()=>window.continueGetDoc);await p.evaluate(()=>test.nav('courses'));assert.equal(await p.evaluate(()=>test.state.page),'teacherManagement');await p.evaluate(()=>test.loggedOut());await p.evaluate(async()=>{pauseGetDoc=false;continueGetDoc();await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)))});assert.equal(await p.evaluate(()=>ops.length),0);assert.equal(await p.locator('#appPanel').isHidden(),true);await p.context().close()});
await check('統合: 勤務曜日外の新規毎週設定を拒否、既存不一致は保持',async()=>{const p=await open('/?work-feature=1');await seedWork(p);await p.evaluate(()=>test.openStudent('s'));assert.equal(await p.evaluate(()=>Object.values(test.collectRegularSlots())[0].teacherUid),'a');await p.locator('[data-field=activeFrom]').fill('2026-02-01');assert.match(await p.evaluate(()=>{try{test.collectRegularSlots();return ''}catch(e){return e.message}}),/通常勤務曜日/);assert.equal(await p.evaluate(()=>mem.get('schoolStudents/s').regularSlots.r.activeUntil),'2026-12-31');await p.context().close()});
