await check('統合: 週間・臨時勤務をバックアップから復元',async()=>{const p=await open('/?work-feature=1');await seedWork(p);await p.evaluate(async()=>{test.state.profile.role='owner';Object.assign(test.maintenanceState,{loaded:true,enabled:true});mem.set('teacherDateWork/2026-11-17_a',{date:'2026-11-17',teacherUid:'a',availablePeriods:[1,2]});const archive=await test.createOwnerArchive('勤務設定付き');mem.set('teacherWeeklyWork/a',{weekdays:[]});mem.delete('teacherDateWork/2026-11-17_a');await test.restoreOwnerArchive({...archive,label:'勤務設定付き'})});assert.deepEqual(await p.evaluate(()=>mem.get('teacherWeeklyWork/a').weekdays),[1,4]);assert.deepEqual(await p.evaluate(()=>mem.get('teacherDateWork/2026-11-17_a').availablePeriods),[1,2]);assert.equal(await p.evaluate(()=>mem.get('teacherWeeklyWork/a').updatedBy),'mgr');await p.context().close()});
await check('統合: 旧バックアップの復元で新しい勤務設定を消さない',async()=>{const p=await open('/?work-feature=1');await seedWork(p);await p.evaluate(async()=>{test.state.profile.role='owner';Object.assign(test.maintenanceState,{loaded:true,enabled:true});mem.delete('teacherWeeklyWork/a');mem.delete('teacherWeeklyWork/b');const archive=await test.createOwnerArchive('旧データ');mem.set('teacherWeeklyWork/a',{weekdays:[1,4]});mem.set('teacherDateWork/2026-11-17_a',{date:'2026-11-17',teacherUid:'a',availablePeriods:[1]});await test.restoreOwnerArchive({...archive,label:'旧データ'})});assert.deepEqual(await p.evaluate(()=>mem.get('teacherWeeklyWork/a').weekdays),[1,4]);assert.equal(await p.evaluate(()=>mem.has('teacherDateWork/2026-11-17_a')),true);await p.context().close()});
await check('統合: 勤務機能無効時に勤務設定付きバックアップを部分復元しない',async()=>{const p=await open();await seed(p,'owner');await p.evaluate(async()=>{Object.assign(test.maintenanceState,{loaded:true,enabled:true});const record={path:'teacherWeeklyWork/a',data:{weekdays:[1]}};mem.set('backupArchives/old',{formatVersion:1,partCount:1,recordCount:1});mem.set('backupArchives/old/parts/00000',{json:JSON.stringify([record])});await test.restoreOwnerArchive({id:'old',label:'勤務含む'})});assert.equal(await p.evaluate(()=>ops.length),0);assert.match(await p.locator('#message').innerText(),/勤務設定/);await p.context().close()});
